-- NEMESIS 1.2.0 idempotent upgrade
ALTER TABLE users ADD COLUMN IF NOT EXISTS level INTEGER NOT NULL DEFAULT 1;
ALTER TABLE users ADD COLUMN IF NOT EXISTS role_tag VARCHAR(32) NOT NULL DEFAULT 'Игрок';
ALTER TABLE users ADD COLUMN IF NOT EXISTS bio TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN IF NOT EXISTS profile_theme VARCHAR(32) NOT NULL DEFAULT 'operative';
ALTER TABLE items ADD COLUMN IF NOT EXISTS status VARCHAR(16) NOT NULL DEFAULT 'owned';
UPDATE items SET status='owned' WHERE status IS NULL;

UPDATE users SET level=1 WHERE level IS NULL;
UPDATE users SET role_tag='Игрок' WHERE role_tag IS NULL OR role_tag='';
UPDATE users SET profile_theme='operative' WHERE profile_theme IS NULL OR profile_theme='';

