-- NEMESIS 1.3.0 additive progression / economy upgrade
ALTER TYPE rarity_type ADD VALUE IF NOT EXISTS 'nemesis';
ALTER TABLE users ADD COLUMN IF NOT EXISTS xp BIGINT NOT NULL DEFAULT 0 CHECK (xp >= 0), ADD COLUMN IF NOT EXISTS total_earned BIGINT NOT NULL DEFAULT 0 CHECK (total_earned >= 0), ADD COLUMN IF NOT EXISTS total_spent BIGINT NOT NULL DEFAULT 0 CHECK (total_spent >= 0), ADD COLUMN IF NOT EXISTS inventory_value BIGINT NOT NULL DEFAULT 0 CHECK (inventory_value >= 0), ADD COLUMN IF NOT EXISTS heat INTEGER NOT NULL DEFAULT 0 CHECK (heat >= 0), ADD COLUMN IF NOT EXISTS kills INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS deaths INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS successful_runs INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS failed_runs INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS extractions INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS failed_extractions INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS total_loot BIGINT NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS biggest_loot BIGINT NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS biggest_loss BIGINT NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS contracts_completed INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS heat_record INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS last_active_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE item_templates DROP CONSTRAINT IF EXISTS rarity_level_match;
ALTER TABLE item_templates ADD COLUMN IF NOT EXISTS category VARCHAR(16) NOT NULL DEFAULT 'BODY', ADD COLUMN IF NOT EXISTS market_value BIGINT NOT NULL DEFAULT 100 CHECK (market_value >= 0), ADD COLUMN IF NOT EXISTS weight NUMERIC(8,2) NOT NULL DEFAULT 1 CHECK (weight >= 0);
ALTER TABLE items ADD COLUMN IF NOT EXISTS condition INTEGER NOT NULL DEFAULT 100 CHECK (condition BETWEEN 0 AND 100), ADD COLUMN IF NOT EXISTS upgrade_level INTEGER NOT NULL DEFAULT 0 CHECK (upgrade_level BETWEEN 0 AND 10), ADD COLUMN IF NOT EXISTS custom_stats JSONB NOT NULL DEFAULT '{}'::JSONB, ADD COLUMN IF NOT EXISTS market_value BIGINT NOT NULL DEFAULT 0 CHECK (market_value >= 0);
CREATE INDEX IF NOT EXISTS idx_items_owner_status ON items(owner_id,status); CREATE INDEX IF NOT EXISTS idx_items_rarity ON items(rarity); CREATE INDEX IF NOT EXISTS idx_items_created ON items(created_at); CREATE INDEX IF NOT EXISTS idx_market_active_price ON market_listings(status,price); CREATE INDEX IF NOT EXISTS idx_market_item ON market_listings(item_id); CREATE INDEX IF NOT EXISTS idx_case_items_case ON case_items(case_id); CREATE INDEX IF NOT EXISTS idx_trades_participants ON trades(initiator_id,recipient_id,status);
CREATE TABLE IF NOT EXISTS resources(user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,metal INTEGER NOT NULL DEFAULT 0 CHECK(metal>=0),parts INTEGER NOT NULL DEFAULT 0 CHECK(parts>=0),electronics INTEGER NOT NULL DEFAULT 0 CHECK(electronics>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS xp_events(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,amount INTEGER NOT NULL CHECK(amount>0),reason VARCHAR(64) NOT NULL,reference_id UUID,created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_xp_events_user_created ON xp_events(user_id,created_at);
CREATE TABLE IF NOT EXISTS contracts(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),kind VARCHAR(16) NOT NULL CHECK(kind IN('daily','weekly')),code VARCHAR(64) NOT NULL,title VARCHAR(128) NOT NULL,target INTEGER NOT NULL CHECK(target>0),reward_money BIGINT NOT NULL DEFAULT 0,reward_xp INTEGER NOT NULL DEFAULT 0,reward_resource VARCHAR(32),reward_amount INTEGER NOT NULL DEFAULT 0,active_from TIMESTAMPTZ NOT NULL DEFAULT now(),active_until TIMESTAMPTZ NOT NULL,UNIQUE(kind,code,active_from));
CREATE TABLE IF NOT EXISTS user_contracts(user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,contract_id UUID NOT NULL REFERENCES contracts(id) ON DELETE CASCADE,progress INTEGER NOT NULL DEFAULT 0 CHECK(progress>=0),claimed BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,contract_id));
CREATE TABLE IF NOT EXISTS achievements(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),code VARCHAR(64) UNIQUE NOT NULL,title VARCHAR(128) NOT NULL,description TEXT NOT NULL,reward_money BIGINT NOT NULL DEFAULT 0,reward_xp INTEGER NOT NULL DEFAULT 0,icon VARCHAR(16) NOT NULL DEFAULT '◇');
CREATE TABLE IF NOT EXISTS user_achievements(user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,achievement_id UUID NOT NULL REFERENCES achievements(id) ON DELETE CASCADE,unlocked_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS item_price_history(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),template_id UUID NOT NULL REFERENCES item_templates(id) ON DELETE CASCADE,price BIGINT NOT NULL CHECK(price>=0),source VARCHAR(32) NOT NULL DEFAULT 'market',created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_price_history_template_created ON item_price_history(template_id,created_at);
CREATE TABLE IF NOT EXISTS black_runs(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,risk VARCHAR(16) NOT NULL CHECK(risk IN('low','medium','high','black')),loadout_value BIGINT NOT NULL DEFAULT 0,loadout_power INTEGER NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK(status IN('active','extracted','dead','abandoned')),loot_value BIGINT NOT NULL DEFAULT 0,loot JSONB NOT NULL DEFAULT '[]'::JSONB,extraction_started_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS idx_black_runs_user_status ON black_runs(user_id,status);
CREATE TABLE IF NOT EXISTS black_run_events(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),run_id UUID NOT NULL REFERENCES black_runs(id) ON DELETE CASCADE,event_type VARCHAR(32) NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seasons(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),code VARCHAR(64) UNIQUE NOT NULL,name VARCHAR(128) NOT NULL,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS seasonal_stats(season_id UUID NOT NULL REFERENCES seasons(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,loot_extracted BIGINT NOT NULL DEFAULT 0,successful_runs INTEGER NOT NULL DEFAULT 0,contracts INTEGER NOT NULL DEFAULT 0,rare_items INTEGER NOT NULL DEFAULT 0,profit BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(season_id,user_id));
INSERT INTO resources(user_id) SELECT id FROM users ON CONFLICT(user_id) DO NOTHING;
INSERT INTO seasons(code,name,starts_at,ends_at,active) SELECT 'S01','BLACK MARKET — SEASON 01',now(),now()+interval '30 days',TRUE WHERE NOT EXISTS(SELECT 1 FROM seasons WHERE code='S01');
INSERT INTO achievements(code,title,description,reward_money,reward_xp,icon) VALUES ('FIRST_CASE','FIRST CASE','Открыть первый кейс',100,50,'▣'),('FIRST_SALE','FIRST SALE','Продать первый предмет',150,75,'₦'),('FIRST_TRADE','FIRST TRADE','Завершить первый обмен',200,100,'⇄'),('FIRST_EXTRACTION','FIRST EXTRACTION','Успешно эвакуироваться из Black Run',300,150,'⌁'),('FIRST_LEGENDARY','FIRST LEGENDARY','Получить Legendary',1000,300,'★'),('CASES_100','100 CASES','Открыть 100 кейсов',5000,1000,'100'),('EARNED_1M','1 000 000₦ EARNED','Заработать 1 000 000₦',10000,2500,'₦'),('RUNS_10','10 SUCCESSFUL RUNS','Успешно завершить 10 рейдов',5000,1500,'10'),('NEMESIS_DROP','NEMESIS DROP','Получить предмет редкости NEMESIS',25000,5000,'N') ON CONFLICT(code) DO NOTHING;
UPDATE item_templates SET market_value=CASE rarity WHEN 'common' THEN GREATEST(75,level*55) WHEN 'uncommon' THEN GREATEST(250,level*120) WHEN 'rare' THEN GREATEST(700,level*260) WHEN 'epic' THEN GREATEST(1800,level*650) WHEN 'legendary' THEN GREATEST(6000,level*1800) WHEN 'nemesis' THEN GREATEST(50000,level*7000) ELSE market_value END,category=CASE type WHEN 'weapon' THEN 'WEAPON' WHEN 'backpack' THEN 'BACKPACK' ELSE 'BODY' END,weight=CASE type WHEN 'weapon' THEN GREATEST(1,level*0.45) WHEN 'backpack' THEN GREATEST(0.8,level*0.3) ELSE GREATEST(1,level*0.65) END;
UPDATE items i SET market_value=t.market_value FROM item_templates t WHERE t.id=i.template_id AND (i.market_value=0 OR i.market_value IS NULL);
ALTER TABLE item_templates ADD COLUMN IF NOT EXISTS equip_slot VARCHAR(16) NOT NULL DEFAULT 'chest';
UPDATE item_templates SET equip_slot=CASE category WHEN 'HEAD' THEN 'helmet' WHEN 'LEGS' THEN 'legs' WHEN 'BACKPACK' THEN 'backpack' WHEN 'WEAPON' THEN 'weapon' ELSE 'chest' END;
UPDATE item_templates SET base_stats=base_stats||jsonb_build_object('power',CASE rarity WHEN 'common' THEN 8 WHEN 'uncommon' THEN 18 WHEN 'rare' THEN 32 WHEN 'epic' THEN 55 WHEN 'legendary' THEN 90 WHEN 'nemesis' THEN 140 ELSE 8 END,'survival',CASE rarity WHEN 'common' THEN 5 WHEN 'uncommon' THEN 12 WHEN 'rare' THEN 22 WHEN 'epic' THEN 38 WHEN 'legendary' THEN 60 WHEN 'nemesis' THEN 90 ELSE 5 END);
